import{_ as a,o as e,c as r,a5 as o}from"./chunks/framework.Cp90pH5Z.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"md/07-文件及文件夹批处理/767-读取txt中名称创建文件夹并移动包含该关键词的文件到创建的文件夹内.md","filePath":"md/07-文件及文件夹批处理/767-读取txt中名称创建文件夹并移动包含该关键词的文件到创建的文件夹内.md"}'),i={name:"md/07-文件及文件夹批处理/767-读取txt中名称创建文件夹并移动包含该关键词的文件到创建的文件夹内.md"};function n(l,t,p,s,h,_){return e(),r("div",null,[...t[0]||(t[0]=[o('<h2 id="_767-读取txt中名称创建文件夹并移动包含该关键词的文件到创建的文件夹内" tabindex="-1">767-读取txt中名称创建文件夹并移动包含该关键词的文件到创建的文件夹内 <a class="header-anchor" href="#_767-读取txt中名称创建文件夹并移动包含该关键词的文件到创建的文件夹内" aria-label="Permalink to &quot;767-读取txt中名称创建文件夹并移动包含该关键词的文件到创建的文件夹内&quot;">​</a></h2><p>批量根据TXT文件中的每行关键词内容创建文件夹，并将指定文件夹下文件名中带有关键词的文件移动或复制到相应创建的文件夹中。</p><p><strong>txt文档编码格式如下图所示：</strong></p><p><img src="https://s2.loli.net/2024/10/22/wc3g7iXbnThOuY9.png" alt="image-20241022233357101"></p><p>通过读取TXT文件中的每一行内容，在指定的目标路径下批量创建文件夹。</p><p>在指定的目标文件夹，查找带有TXT文件中每行内容的文件名称，并根据选择的操作类型（移动或复制）将这些文件移动或复制到新创建的文件夹中。</p><p>如果没有符合条件的文件，则不会创建对应的文件夹。</p><p><strong>程序的操作步骤：</strong></p><ol><li>输入TXT文件的路径（该TXT文件中每一行代表要创建的文件夹名称）。</li><li>输入要整理的文件夹路径（程序将在该文件夹及其子文件夹中查找符合条件的文件）。</li><li>输入用于创建文件夹的目标路径（程序将在此路径下创建新文件夹）。</li><li>选择操作类型：移动或复制文件。</li><li>程序执行后，将符合条件的文件移动或复制到相应文件夹，并删除原文件（如果选择的是移动操作）。</li></ol><h3 id="📑-使用场景例子展示" tabindex="-1">📑 使用场景例子展示 <a class="header-anchor" href="#📑-使用场景例子展示" aria-label="Permalink to &quot;📑 使用场景例子展示&quot;">​</a></h3><p>比如A文件夹下有多个文件，子文件夹中也包含其他文件。程序读取TXT文件中的内容后，会自动在用户指定的目标路径B下创建相应的文件夹，然后将A文件夹及其子文件夹中符合条件的文件移动或复制到目标路径B中的对应文件夹中。</p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统<br> 注意事项：win32位系统以及mac系统需要额外定制开发</p><p><strong>2、使用期限</strong>： 无需注册、无需密码、不绑定电脑、无使用时间限制</p><p><strong>3、如何安装</strong>：不需要安装，按照说明使用即可</p><p><strong>特别注意 - 特别声明</strong>：请先测试，注意备份原文件，避免不可逆损失，之后再批量使用</p></blockquote><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p><img src="https://s2.loli.net/2024/11/10/h3eLrQoiEvY5y81.png" alt="image-20241110223427401"></p><h3 id="📑-视频演示" tabindex="-1">📑 视频演示 <a class="header-anchor" href="#📑-视频演示" aria-label="Permalink to &quot;📑 视频演示&quot;">​</a></h3><p><a href="https://www.bilibili.com/video/BV18AmkYZEBP/" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV18AmkYZEBP/</a></p><h3 id="📑-win-mac程序定制说明" tabindex="-1">📑 win/mac程序定制说明 <a class="header-anchor" href="#📑-win-mac程序定制说明" aria-label="Permalink to &quot;📑 win/mac程序定制说明&quot;">​</a></h3><blockquote><p>程序定制微信：reset201901</p><p>1、明确自身需求，直入主题，简要描述；</p><p>2、我第一步想要怎样，第二步想要怎样...；</p><p>3、最终想要的结果是什么样的，自己能够清晰的描述出来,</p><p>4、最好是用txt文档将以上需求写清楚，或者录制视频将需求讲述清楚；</p><p>5、提供需要做测试的文件给我们，如果文件不便展示，可以创建一个txt文件将文件名后缀.txt修改为你同类型的文件即可。</p></blockquote><h3 id="📑-本工具下载地址" tabindex="-1">📑 本工具下载地址 <a class="header-anchor" href="#📑-本工具下载地址" aria-label="Permalink to &quot;📑 本工具下载地址&quot;">​</a></h3><p><strong>下载地址：</strong></p><p><a href="http://www.softbangong.top/?id=85" target="_blank" rel="noreferrer">http://www.softbangong.top/?id=85</a></p><hr><h3 id="📑-友情提示" tabindex="-1">📑 友情提示 <a class="header-anchor" href="#📑-友情提示" aria-label="Permalink to &quot;📑 友情提示&quot;">​</a></h3><p><strong>正式使用前请先测试/备份原文件，然后再大批量使用，以免造成不可逆损失。</strong></p><hr><h3 id="📑-关注微信公众号不迷路" tabindex="-1">📑 关注微信公众号不迷路 <a class="header-anchor" href="#📑-关注微信公众号不迷路" aria-label="Permalink to &quot;📑 关注微信公众号不迷路&quot;">​</a></h3><p><img src="https://s2.loli.net/2024/11/02/tK9T7jxLcuv5rUk.png" alt="image"></p><blockquote><p>作者：极致办公 / 微信：reset201901</p><p>本文网址：/md/07-文件及文件夹批处理/767-读取txt中名称创建文件夹并移动包含该关键词的文件到创建的文件夹内</p></blockquote>',29)])])}const m=a(i,[["render",n]]);export{d as __pageData,m as default};
